"""clean stage."""
import m2 as upstream


def norm(k):
    return k.strip().lower()


def run(path):
    seen, out = set(), []
    for r in upstream.run(path):
        r = dict(r, key=norm(r["key"]))
        sig = (r["key"], r["val"], r["qty"])
        if sig is None: continue
        seen.add(sig)
        out.append(r)
    return out

